/*
 * VATFLOW Tower Cab - screen host: every 1024x768 cab screen runs this gauge and shows one
 * app, chosen with the MENU tab in the screen's bottom-right corner (the choice is kept per
 * screen in the sim's storage). Apps: TOWER RADAR (DBRITE), GROUND RADAR (ASDE-X), IDST, VATSMART, APT DASHBOARD demand
 * and list, RAMP (the ramp map of any airport on vatflow.io's ramp page), the KDCA ramp
 * list (KDCA only), STRIP BAYS and the tower SETUP screen.
 * Screens are described in Screen/S_<id>.js (generated by tools/build_screens.py).
 *
 * Each app's timers and network callbacks belong to it (VatflowOwner), so switching apps
 * stops the old one instead of leaving it polling in the background.
 */
var VatflowOwner = (function () {
  var cur = null;
  var root = typeof window !== "undefined" ? window : this;
  var st = root.setTimeout, si = root.setInterval, ci = root.clearInterval;

  function wrap(fn, o) {
    return function () {
      if (o && o.dead) return undefined;
      var prev = cur;
      cur = o;
      try { return fn.apply(this, arguments); } finally { cur = prev; }
    };
  }

  root.setTimeout = function (fn, ms) {
    if (typeof fn !== "function") return st.call(root, fn, ms);
    return st.call(root, wrap(fn, cur), ms);
  };
  root.setInterval = function (fn, ms) {
    if (typeof fn !== "function") return si.call(root, fn, ms);
    var o = cur, id;
    id = si.call(root, function () {
      if (o && o.dead) { ci.call(root, id); return; }
      var prev = cur;
      cur = o;
      try { fn(); } finally { cur = prev; }
    }, ms);
    return id;
  };
  if (typeof XMLHttpRequest !== "undefined") {
    var send = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function (body) {
      var o = cur, x = this, ks = ["onload", "onerror", "ontimeout", "onreadystatechange"];
      if (o) for (var i = 0; i < ks.length; i++) if (typeof x[ks[i]] === "function") x[ks[i]] = wrap(x[ks[i]], o);
      return send.call(this, body);
    };
  }

  /** Runs fn with owner o (timers / requests it starts belong to o). */
  function run(o, fn) {
    var prev = cur;
    cur = o;
    try { return fn(); } finally { cur = prev; }
  }
  return { run: run, current: function () { return cur; } };
})();

var VatflowApps = (function () {
  function canvas(el, cls, id) {
    el.innerHTML = '<canvas ' + (id ? 'id="' + id + '" ' : "") + (cls ? 'class="' + cls + '" ' : "") + 'width="1024" height="768"></canvas>';
    return el.querySelector("canvas");
  }
  function every(ms, fn) {
    var last = 0;
    return function () {
      var now = Date.now();
      if (now - last < ms) return;
      last = now;
      try { fn(now); } catch (e) { if (typeof console !== "undefined") console.error("VATFLOW app", (e && e.stack) || e); }
    };
  }
  var kdcaOnly = function (cfg) { return cfg.icao === "KDCA"; };

  var NO_MAPS = "NO ARTCC VIDEO MAPS INSTALLED FOR THIS AIRPORT. PUT THE ARTCC FILE (E.G. ZTL.JSON FROM VNAS) IN THE " +
    "vatflow-towercab-maps PACKAGE'S \"ARTCC files\" FOLDER AND RUN update-maps.bat THERE (SEE ITS README). " +
    "UNTIL THEN THE BUILT-IN MAP IS SHOWN.";

  /**
   * MAPS button for a radar app: lists the ARTCC's video maps for this airport (VatflowVnas)
   * and hands the chosen ones, loaded and converted, to apply(list). kind: "dbrite" (any
   * number of STARS / cab maps) or "asdex" (one map: the facility's ASDE-X map, a cab map,
   * or the built-in one).
   */
  function videoMaps(el, ctx, kind, apply) {
    var cfg = ctx.cfg, converted = {}, token = 0;
    VatflowVnas.facility(cfg.icao, cfg.lid, function (info) {
      var items = [], meta = {}, defaults = [], presets = [];
      function add(e, label) {
        if (!e || meta[e.id]) return;
        meta[e.id] = e;
        items.push({ id: e.id, label: label });
      }
      if (info && kind === "dbrite") {
        (info.cabMaps || []).concat(info.cabMap ? [info.cabMap] : []).forEach(function (e) { add(e, "CAB  " + e.name); });
        info.stars.forEach(function (e) { add(e, (e.stars ? (e.stars < 10 ? " " : "") + e.stars : "--") + " " + e.name); });
        presets = info.configs.length ? info.configs : ["PRESET 1", "PRESET 2", "PRESET 3"];
      } else if (info) {
        items.push({ id: "osm", label: "BUILT-IN (OPENSTREETMAP)" });
        add(info.asdexMap, "ASDE-X  " + (info.asdexMap ? info.asdexMap.name : ""));
        info.asdexMaps.forEach(function (e) { add(e, "ASDE-X  " + e.name); });
        info.cabMaps.forEach(function (e) { add(e, "CAB  " + e.name); });
        defaults = [info.asdexMap ? info.asdexMap.id : "osm"];
      }
      var picker = new VatflowMapPicker(el, {
        app: kind, icao: cfg.icao, multi: kind === "dbrite", items: items, defaults: defaults, presets: presets,
        title: info ? info.artcc + (info.tracon ? " " + info.tracon : "") + " / " + info.lid + " " + (info.name || "") : cfg.icao,
        note: NO_MAPS + "   DETAILS: " + VatflowVnas.reason(cfg.icao), onChange: load
      });
      function load(ids) {
        var my = ++token, list = [], left = ids.length, failed = 0;
        if (!info || !left) { apply([]); picker.setStatus(""); return; }
        picker.setStatus("LOADING " + left + " MAP" + (left > 1 ? "S" : "") + " FROM VNAS...");
        ids.forEach(function (id, i) {
          if (id === "osm" || !meta[id]) { finish(); return; }
          if (converted[id]) { list[i] = converted[id]; finish(); return; }
          VatflowVnas.loadMap(info.artcc, id, function (err, gj) {
            if (err || !gj) failed++;
            else {
              var m = meta[id];
              converted[id] = kind === "asdex" ? VatflowVnas.toAsdex(gj, cfg.arp)
                : Object.assign(VatflowVnas.toLines(gj, cfg.arp), { stars: m.tags.indexOf("STARS") >= 0 && !!m.stars, cat: m.cat });
              list[i] = converted[id];
            }
            finish();
          });
        });
        function finish() {
          if (--left > 0 || my !== token) return;
          apply(list.filter(Boolean));
          picker.setStatus(failed ? failed + " MAP(S) COULD NOT BE LOADED FROM VNAS" : ids.length + " ON");
        }
      }
      load(picker.selected());
    });
  }
  /** Zoom / pan pad for a radar view (kept per screen). */
  function zoomPan(el, ctx, app, view, redraw, padOpts) {
    var c = el.querySelector("canvas");
    var vc = new VatflowViewCtl("VIEW_" + app + "_" + ctx.screen.id, c.width, c.height);
    view.setView(vc);
    vc.onChange = redraw;
    vc.pad(el, padOpts);
    return vc;
  }

  var rampLayout = function () { return typeof VATFLOW_RAMP_LAYOUT !== "undefined" ? VATFLOW_RAMP_LAYOUT : null; };

  var IDST_HTML = '<div id="id-root"><div class="id-top"><span class="id-title">VATFLOW IDST</span><span id="id-icao" class="id-icao">----</span>' +
    '<span id="id-auth" class="id-auth">--</span><span id="id-zulu" class="id-zulu">----:--Z</span></div>' +
    '<div class="id-head id-row"><span class="c-cs">CALLSIGN</span><span class="c-type">TYPE</span><span class="c-dest">DEST</span>' +
    '<span class="c-fca">PROGRAM</span><span class="c-rel">RELEASE</span><span class="c-state">STATUS</span></div>' +
    '<div id="id-list" class="id-list"></div><div id="id-msg" class="id-msg"></div><div class="id-keys">' +
    '<div id="id-up" class="id-key">UP</div><div id="id-down" class="id-key">DN</div>' +
    '<div id="id-issue" class="id-key id-issue">ISSUE RELEASE</div><div id="id-cancel" class="id-key id-cancel">CANCEL</div></div>' +
    '<div id="id-status" class="id-status"></div></div>';
  var VS_HTML = '<div id="vs-root"><div class="vs-top"><span class="vs-brand">VAT<span>SMART</span></span><span id="vs-icao" class="vs-icao">----</span>' +
    '<span id="vs-pills" class="vs-pills"></span><span id="vs-zulu" class="vs-zulu">----Z</span></div><div id="vs-kpis" class="vs-kpis"></div>' +
    '<canvas id="vs-chart" class="vs-chart" width="996" height="236"></canvas><div class="vs-row">' +
    '<div class="vs-panel vs-left"><div class="vs-ph">RECOMMENDATIONS</div><div id="vs-recs"></div></div>' +
    '<div class="vs-panel vs-right"><div class="vs-ph">GATES - MIT PLAN</div><div id="vs-gates"></div></div></div><div id="vs-err" class="vs-err"></div></div>';
  var AL_HTML = '<div id="al-root"><div class="al-top"><span class="al-title">APT DASHBOARD</span><span id="al-icao" class="al-icao">----</span>' +
    '<span id="al-prog" class="al-prog"></span><span id="al-zulu" class="al-zulu">----Z</span></div>' +
    '<div class="al-sub">AIRCRAFT LIST - METERED ORDER (STA)</div><div id="al-head" class="al-row al-head"></div><div id="al-body"></div>' +
    '<div id="al-foot" class="al-foot"></div></div>';
  var RP_HTML = '<div id="rp-root"><div class="rp-top"><span class="rp-title">GATES</span><span id="rp-icao" class="rp-icao">KDCA</span>' +
    '<span id="rp-status" class="rp-status">connecting...</span><span id="rp-zulu" class="rp-zulu">----Z</span></div><div class="rp-cols">' +
    '<div class="rp-sec"><div class="rp-h">INBOUND <span id="rp-inCount"></span></div><div class="rp-row rp-head"><span class="c1">CALLSIGN</span>' +
    '<span class="c2">TYPE</span><span class="c3">FROM</span><span class="c4">ETA</span><span class="c5">GATE</span><span class="c6"></span></div><div id="rp-in"></div></div>' +
    '<div class="rp-sec"><div class="rp-h">OUTBOUND <span id="rp-outCount"></span></div><div class="rp-row rp-head"><span class="c1">CALLSIGN</span>' +
    '<span class="c2">TYPE</span><span class="c3">TO</span><span class="c5">GATE</span><span class="c7">STATUS</span><span class="c4">P-TIME</span></div><div id="rp-out"></div></div></div>' +
    '<div class="rp-foot"><span class="asg">ASSIGNED</span> ramp board &nbsp; <span class="real">REAL</span> today\'s real flight &nbsp; <span class="prop">PROP</span> airline\'s gates</div></div>';

  /** A ramp map screen's first view: KDCA's named one, else the airport's rampN-th (none named: all). */
  function defaultViews(raw, screen) {
    var pv = RampMapView.pickViews(raw);
    for (var i = 0; i < pv.length; i++) if (pv[i].id === screen.ramp) return [pv[i].id];
    return screen.rampN != null && pv.length > 1 ? [pv[screen.rampN % pv.length].id] : [];
  }

  /**
   * The radars' traffic tab (left of MAPS): shows where the traffic comes from (VATSIM / SIM,
   * common/traffic.js) and switches it for every screen when tapped. Returns update().
   */
  function trafficTab(el, changed) {
    var doc = el.ownerDocument || document, tab = doc.createElement("div"), shown = null;
    tab.style.cssText = "position:absolute;right:182px;bottom:0;width:96px;height:34px;background:#1b2a3a;" +
      "border:2px solid #35506b;color:#cfe0f0;font:bold 18px monospace;display:flex;align-items:center;" +
      "justify-content:center;z-index:900;opacity:0.85;";
    el.appendChild(tab);
    tab.addEventListener("mouseup", function (ev) {
      if (ev && ev.stopPropagation) ev.stopPropagation();
      VatflowTraffic.setSource(VatflowTraffic.source() === "SIM" ? "VATSIM" : "SIM");
      update();
      if (changed) changed();
    });
    function update() {
      var s = VatflowTraffic.source();
      if (s !== shown) { tab.textContent = s; tab.style.color = s === "SIM" ? "#7dffa0" : "#cfe0f0"; shown = s; }
    }
    update();
    return update;
  }

  /** A canvas view that only says something (loading, nothing picked yet). */
  function note(cv, text) {
    return {
      canvas: cv,
      draw: function () {
        var g = cv.getContext("2d");
        g.setTransform(1, 0, 0, 1, 0, 0);
        g.fillStyle = "#0b0f14";
        g.fillRect(0, 0, cv.width, cv.height);
        g.fillStyle = "#7f93a8";
        g.font = "bold 26px monospace";
        g.textAlign = "center";
        g.fillText(text, cv.width / 2, cv.height / 2);
      }
    };
  }

  var APPS = {
    dbrite: {
      label: "TOWER RADAR", tag: "vatflow-dbrite", maps: true,
      create: function (el, ctx) {
        var v = new DbriteView(canvas(el, null, "dbrite-canvas"), ctx.cfg, ctx.maps);
        var tick = VatflowDraw.loop(v, 1000);
        zoomPan(el, ctx, "dbrite", v, function () { tick(true); });
        var src = trafficTab(el);
        VatflowTraffic.poll(ctx.cfg, function (d) { v.setData(d); }, function (e) { v.setError(e); });
        VatflowFeed.pollMetars(ctx.cfg.dbrite.altimeterStations, function (m) { v.setMetars(m); });
        videoMaps(el, ctx, "dbrite", function (list) { v.setVideoMaps(list); tick(true); });
        return { update: function () { src(); tick(false); } };
      }
    },
    asdex: {
      label: "GROUND RADAR", tag: "vatflow-asdex", maps: true,
      create: function (el, ctx) {
        var v = new AsdexView(canvas(el, null, "asdex-canvas"), ctx.cfg, ctx.maps);
        var tick = VatflowDraw.loop(v, 1000);
        // the rotate row: turn the map by hand in 15 degree steps, or AUTO (the view out of the window)
        var vc = zoomPan(el, ctx, "asdex", v, function () { v.setUp(vc.upHeading(ctx.upHeading())); v.fit(); tick(true); },
          { rotate: function () { return v.upHdg; } });
        var src = trafficTab(el);
        VatflowTraffic.poll(ctx.cfg, function (d) { v.setData(d); }, function (e) { v.setError(e); });
        videoMaps(el, ctx, "asdex", function (list) { v.setMap(list.length ? list[0].asdex || list[0] : (ctx.maps ? ctx.maps.asdex : null)); tick(true); });
        return { update: function () { src(); v.setUp(vc.upHeading(ctx.upHeading())); v.rotManual = vc.rot !== null; tick(false); } };
      }
    },
    idst: {
      label: "IDST RELEASES", tag: "vatflow-idst",
      create: function (el, ctx) {
        el.innerHTML = IDST_HTML;
        var v = new IdstView(el.querySelector("#id-root"), ctx.cfg);
        v.start();
        var cidAt = -1;
        var draw = every(1000, function () {
          // the CID is typed on the SETUP screen (another screen): pick it up when it changes
          var t = typeof SimVar !== "undefined" ? SimVar.GetSimVarValue("L:VATFLOW_CID_CHANGED", "number") : 0;
          if (t !== cidAt) { cidAt = t; ctx.cfg.idst.cid = VatflowStore.get("CID", "") || ""; }
          v.render();
        });
        return {
          update: function () {
            if (ctx.screen.id === "IDST" && typeof SimVar !== "undefined") {
              var k = SimVar.GetSimVarValue("L:VATFLOW_IDST_KEY", "number");
              if (k) { SimVar.SetSimVarValue("L:VATFLOW_IDST_KEY", "number", 0); v.key(Math.round(k)); }
            }
            draw();
          }
        };
      }
    },
    vatsmart: {
      label: "VATSMART", tag: "vatflow-vatsmart",
      create: function (el, ctx) {
        el.innerHTML = VS_HTML;
        var v = new VatsmartView(el.querySelector("#vs-root"), el.querySelector("#vs-chart"), ctx.cfg);
        v.start();
        var tick = VatflowDraw.loop(v, 1000);
        return { update: function () { tick(false); } };
      }
    },
    aptdemand: {
      label: "DEMAND vs AAR", tag: "vatflow-aptdemand",
      create: function (el, ctx) {
        var data = new VatflowAptData(ctx.cfg);
        data.start();
        var v = new AptDemandView(canvas(el, "ad-canvas"), ctx.cfg, data);
        var tick = VatflowDraw.loop(v, 2000);
        return { update: function () { tick(false); } };
      }
    },
    aptlist: {
      label: "AIRCRAFT LIST", tag: "vatflow-aptlist",
      create: function (el, ctx) {
        el.innerHTML = AL_HTML;
        var data = new VatflowAptData(ctx.cfg);
        data.start();
        var v = new AptListView(el.querySelector("#al-root"), ctx.cfg, data);
        return { update: every(2000, function () { v.render(); }) };
      }
    },
    rampmap: {
      // any airport on vatflow.io's ramp page, any of its ramps: picked per screen
      // (VatflowStore "RAMPSEL_<screen>" = {icao, views}); home: it opens on its own map at startup
      label: "RAMP", tag: "vatflow-rampmap", home: function (cfg) { return VatflowRampData.has(cfg.icao); },
      create: function (el, ctx) {
        var key = "RAMPSEL_" + ctx.screen.id, cv = canvas(el, "rm-canvas"), cur = null, my = 0;
        // not picked yet: this airport, the screen's own view (worked out once the layout is in)
        var here = ctx.cfg.icao;
        var sel = VatflowStore.get(key, null) || (VatflowRampData.has(here) ? { icao: here, views: null } : null);
        // one draw loop for the screen, drawing whatever it shows now (each loop keeps its own
        // timer, so a loop per view left the old ones painting over the new one)
        var showing = note(cv, "RAMP MAP - TAP RAMPS TO PICK AN AIRPORT");
        var tick = VatflowDraw.loop({ canvas: cv, draw: function (n, z) { showing.draw(n, z); } }, 2000);
        function display(v) { showing = v; tick(true); }
        function show(s, remember) {                              // remember: picked, not the screen's default
          var token = ++my;
          sel = s;
          if (remember) VatflowStore.set(key, s);
          cur = null;
          function ready(raw) {
            if (token !== my) return;
            if (!raw) { display(note(cv, "COULD NOT LOAD THE " + s.icao + " RAMP LAYOUT")); return; }
            if (!s.views) s.views = defaultViews(raw, ctx.screen);
            cur = new RampMapView(cv, null, s.views, VatflowRampData.shared(s.icao, raw, ctx.cfg.feedUrl));
            cur.upHdg = ctx.upHeading();
            cur.boots = ctx.boots;
            display(cur);
          }
          var have = VatflowRampData.cached(s.icao);
          if (have) { ready(have); return; }                     // loaded already: no LOADING flash
          display(note(cv, "LOADING " + s.icao + " RAMPS..."));
          VatflowRampData.layout(s.icao, ready);
        }
        var picker = new RampPicker(el, { here: ctx.cfg.icao, current: function () { return sel; }, onPick: function (s) { show(s, true); } });
        if (sel) show(sel, false);
        if (ctx.fresh || !sel) picker.open();
        return {
          update: function () { if (cur) cur.upHdg = ctx.upHeading(); tick(false); },
          menu: function () { picker.open(); }                    // RAMP picked again in MENU
          // (no stop: the airport's live data is shared and stays running for the next screen)
        };
      }
    },
    rvr: {
      // the FAA's live RVR table for the cab's airport (Rvr/Rvr.js)
      label: "RVR", tag: "vatflow-rvr",
      create: function (el, ctx) {
        var v = new RvrView(el, ctx.cfg);
        v.start();
        return { update: every(2000, function () { v.render(); }) };
      }
    },
    ramp: {
      label: "RAMP LIST", tag: "vatflow-ramplist", available: kdcaOnly,
      create: function (el, ctx) {
        el.innerHTML = RP_HTML;
        var v = new RampView(el.querySelector("#rp-root"), rampLayout());
        v.start(ctx.cfg.feedUrl);
        return { update: every(2000, function () { v.render(); }) };
      }
    },
    stripsetup: {
      label: "STRIP BAYS", tag: "vatflow-stripsetup",
      create: function (el) {
        var v = new StripSetupView(el);
        v.start();
        return { update: function () {} };
      }
    },
    setup: {
      label: "TOWER SETUP", tag: "vatflow-setup",
      create: function (el, ctx) {
        var v = new SetupView(el, ctx.cfg);
        v.start();
        return { update: every(400, function () { v.render(); }) };
      }
    }
  };
  var ORDER = ["dbrite", "asdex", "idst", "vatsmart", "aptdemand", "aptlist", "rampmap", "ramp", "rvr", "stripsetup", "setup"];
  // apps since folded into others (a screen's saved choice may still name them)
  var RENAMED = { rampED: "rampmap", rampCB: "rampmap", rampAS: "rampmap" };

  function list(cfg) {
    var out = [];
    for (var i = 0; i < ORDER.length; i++) {
      var a = APPS[ORDER[i]];
      if (!a.available || a.available(cfg)) out.push(ORDER[i]);
    }
    return out;
  }

  /** The app a screen opens at startup: its saved choice, else its default (if it suits this airport), else alt. */
  function initial(screen, cfg, saved) {
    var avail = list(cfg);
    saved = RENAMED[saved] || saved;
    if (saved && avail.indexOf(saved) >= 0) return saved;
    var d = APPS[screen.def];
    if (d && avail.indexOf(screen.def) >= 0 && (!d.home || d.home(cfg))) return screen.def;
    return screen.alt || "setup";
  }

  return { APPS: APPS, ORDER: ORDER, list: list, initial: initial };
})();

/**
 * One screen: root element, screen description {id, group, def, alt, faceDeg | mount, ramp}.
 * def: the app it shows until you pick another; alt: what to show instead where def doesn't
 * suit the airport (the ramp map screens where vatflow.io has no ramp layout); ramp: the
 * view a RAMP screen starts on.
 */
var ScreenHost = (function () {
  var MENU_CSS = "position:absolute;right:0;bottom:0;width:86px;height:34px;background:#1b2a3a;border:2px solid #35506b;" +
    "color:#cfe0f0;font:bold 18px monospace;display:flex;align-items:center;justify-content:center;z-index:900;opacity:0.85;";
  var BANNER_CSS = "position:absolute;left:0;right:0;top:0;height:40px;background:#7a4a00;color:#fff3d6;font:bold 20px monospace;" +
    "display:none;align-items:center;justify-content:center;z-index:900;";
  var LIST_CSS = "position:absolute;left:0;top:0;right:0;bottom:0;background:rgba(6,10,15,0.96);z-index:950;display:none;" +
    "flex-wrap:wrap;align-content:flex-start;padding:24px;box-sizing:border-box;font-family:monospace;";
  var ITEM_CSS = "box-sizing:border-box;width:308px;height:96px;margin:0 16px 16px 0;background:#1b2a3a;border:2px solid #35506b;" +
    "color:#e8f1fa;font:bold 24px monospace;display:flex;align-items:center;justify-content:center;text-align:center;";

  // how many times each screen has started this flight (shown in its MENU: should stay 1).
  // An L: var, so it counts a page the sim reloaded too.
  var boots = {};
  function countBoot(id) {
    if (typeof SimVar === "undefined") return (boots[id] = (boots[id] || 0) + 1);
    var n = (SimVar.GetSimVarValue("L:VATFLOW_BOOT_" + id, "number") || 0) + 1;
    SimVar.SetSimVarValue("L:VATFLOW_BOOT_" + id, "number", n);
    return n;
  }

  function ScreenHost(root, screen, cfg, doc) {
    this.boots = countBoot(screen.id);
    this.doc = doc || document;
    this.root = root;
    this.screen = screen;
    this.cfg = cfg;
    this.app = null;
    this.appId = null;
    root.style.position = "relative";
    root.style.overflow = "hidden";
    root.style.background = "#000";
    this.box = this.el("div", "position:absolute;left:0;top:0;width:100%;height:100%;");
    this.msg = this.el("div", "position:absolute;left:0;top:0;width:100%;height:100%;display:flex;align-items:center;" +
      "justify-content:center;color:#7f93a8;font:bold 28px monospace;background:#0a0f16;");
    this.msg.textContent = "LOCATING AIRPORT...";
    this.banner = this.el("div", BANNER_CSS);
    this.banner.textContent = "NOT IN THE TOWER - TAP HERE FOR TOWER SETUP";
    this.list = this.el("div", LIST_CSS);
    this.menu = this.el("div", MENU_CSS);
    this.menu.textContent = "MENU";
    var self = this;
    this.on(this.menu, function () { self.toggleMenu(); });
    this.on(this.banner, function () { self.pick("setup", true); });
    this.on(this.list, function () { self.toggleMenu(false); });
  }

  ScreenHost.prototype.el = function (tag, css) {
    var e = this.doc.createElement(tag);
    e.style.cssText = css;
    this.root.appendChild(e);
    return e;
  };

  ScreenHost.prototype.on = function (e, fn) {
    e.addEventListener("mouseup", function (ev) { if (ev && ev.stopPropagation) ev.stopPropagation(); fn(); });
  };

  /** Up direction for map apps: which way this screen's window (or monitor) looks, degrees true. */
  ScreenHost.prototype.upHeading = function () {
    var s = this.screen;
    if (s.mount && typeof SimVar !== "undefined") {
      var track = SimVar.GetSimVarValue("L:VATFLOW_" + s.mount + "_TRACK_DEG", "number") || 0;
      var twist = SimVar.GetSimVarValue("L:VATFLOW_" + s.mount + "_POSE_SET", "number")
        ? SimVar.GetSimVarValue("L:VATFLOW_" + s.mount + "_TWIST", "number") : 50;
      return VatflowDraw.windowHeading(s.faceDeg + track + (twist - 50));
    }
    return VatflowDraw.windowHeading(s.faceDeg || 0);
  };

  ScreenHost.prototype.start = function () {
    var self = this;
    VatflowSite.resolve(function (site) {
      if (self.dead) return;
      // the airport settings must be this airport's, even if this screen got a fresh copy of the
      // defaults (KDCA) after the airport was found
      if (site && self.cfg.icao !== site.icao) {
        VatflowSite.apply(self.cfg, site, typeof VATFLOW_TWR_OVERRIDES !== "undefined" ? VATFLOW_TWR_OVERRIDES : null);
      }
      self.pick(VatflowApps.initial(self.screen, self.cfg, VatflowStore.get("SCREEN_" + self.screen.id, null)), false);
    });
  };

  ScreenHost.prototype.toggleMenu = function (show) {
    show = show === undefined ? this.list.style.display === "none" : show;
    if (show) {
      var self = this, ids = VatflowApps.list(this.cfg);
      this.list.innerHTML = "";
      ids.forEach(function (id) {
        var it = self.doc.createElement("div");
        it.style.cssText = ITEM_CSS + (id === self.appId ? "background:#7fc8ff;color:#0a0f16;border-color:#7fc8ff;" : "");
        it.textContent = VatflowApps.APPS[id].label;
        self.on(it, function () { self.toggleMenu(false); self.pick(id, true); });
        self.list.appendChild(it);
      });
      var note = self.doc.createElement("div");
      note.style.cssText = "width:100%;color:#7f93a8;font:18px monospace;margin-top:6px;";
      note.textContent = "SCREEN " + this.screen.id + " - " + (this.cfg.icao || "") + (this.boots > 1 ? " - STARTED " + this.boots + " TIMES" : "") +
        " - TAP AN APP, OR ANYWHERE ELSE TO CLOSE";
      this.list.appendChild(note);
    }
    this.list.style.display = show ? "flex" : "none";
  };

  /** Shows app id (remember: keep it as this screen's choice). */
  ScreenHost.prototype.pick = function (id, remember) {
    if (remember) VatflowStore.set("SCREEN_" + this.screen.id, id);
    if (id === this.appId) {
      if (remember && this.app && this.app.menu) this.app.menu();        // e.g. RAMP again: its picker
      return;
    }
    this.stopApp();
    var def = VatflowApps.APPS[id], self = this;
    if (!def) return;
    this.appId = id;
    var owner = this.owner = { dead: false, id: id };
    this.box.innerHTML = "";
    var el = this.doc.createElement(def.tag);
    el.style.cssText = "display:block;width:100%;height:100%;";
    this.box.appendChild(el);
    // fresh: picked in MENU just now (not restored at startup)
    var ctx = { cfg: this.cfg, maps: null, screen: this.screen, fresh: !!remember, boots: this.boots, upHeading: function () { return self.upHeading(); } };
    function create() {
      if (owner.dead) return;
      VatflowOwner.run(owner, function () {
        try {
          self.app = def.create(el, ctx);
          self.msg.style.display = "none";
        } catch (e) {
          self.msg.style.display = "flex";
          self.msg.textContent = "ERR " + String((e && e.message) || e).slice(0, 60);
          if (typeof console !== "undefined") console.error("VATFLOW screen", (e && e.stack) || e);
        }
      });
    }
    if (def.maps) {
      this.msg.style.display = "flex";
      this.msg.textContent = "LOADING " + (this.cfg.icao || "") + " MAP...";
      VatflowOwner.run(owner, function () {
        VatflowSite.loadData(function (d, err) {
          ctx.maps = d ? d.maps : null;
          create();
          if (err && self.app) self.flash("NO MAP: " + err.message);
        });
      });
    } else {
      create();
    }
  };

  ScreenHost.prototype.flash = function (text) {
    this.banner.style.display = "flex";
    this.banner.textContent = text;
    this.flashAt = Date.now();
  };

  ScreenHost.prototype.stopApp = function () {
    if (this.owner) this.owner.dead = true;
    if (this.app && this.app.stop) { try { this.app.stop(); } catch (e) { /* gone anyway */ } }
    this.app = null;
    this.appId = null;
  };

  /** Stops for good (the screen was taken down). */
  ScreenHost.prototype.shutdown = function () {
    this.dead = true;
    this.stopApp();
  };

  ScreenHost.prototype.update = function () {
    if (this.dead) return;
    if (this.app) {
      var self = this;
      VatflowOwner.run(this.owner, function () {
        try { self.app.update(); } catch (e) { if (typeof console !== "undefined") console.error("VATFLOW app", (e && e.stack) || e); }
      });
    }
    // banner: the cab isn't in the tower (only in the sim, not over the SETUP app itself)
    var now = Date.now();
    if (this.flashAt && now - this.flashAt < 8000) return;
    this.flashAt = 0;
    var placed = typeof SimVar === "undefined" ? 1 : SimVar.GetSimVarValue("L:VATFLOW_PLACED", "number");
    var show = !placed && this.appId !== "setup" && VatflowSite.current();
    this.banner.textContent = "NOT IN THE TOWER - TAP HERE FOR TOWER SETUP";
    this.banner.style.display = show ? "flex" : "none";
  };

  return ScreenHost;
})();

/** MSFS wrapper: one per screen (Screen/S_<id>.js calls this). */
function vatflowRegisterScreen(screen) {
  if (typeof BaseInstrument === "undefined") return;
  var tag = "vatflow-screen-" + screen.id.toLowerCase(), templateId = "VatflowScreen" + screen.id;
  class VatflowScreen extends BaseInstrument {
    get templateID() { return templateId; }
    // Lets the sim pass mouse clicks on the screen through to the page (menu, IDST, SETUP).
    get isInteractive() { return true; }
    connectedCallback() {
      super.connectedCallback();
      this.dim = VatflowDimmer.attach(this, screen.group);
      if (screen.mount) VatflowDimmer.initMonitorPose(screen.mount);
      // the sim can attach a screen again (or a second copy of it): the old one stops first,
      // so two never run (and poll) at once
      var old = vatflowRegisterScreen.hosts[screen.id];
      if (old) old.shutdown();
      if (this.host && this.host !== old) this.host.shutdown();
      this.host = vatflowRegisterScreen.hosts[screen.id] = new ScreenHost(this.querySelector(".scr-root"), screen, VATFLOW_TWR);
      this.host.start();
    }
    disconnectedCallback() {
      if (super.disconnectedCallback) super.disconnectedCallback();
      if (this.host) this.host.shutdown();
    }
    Update() {
      super.Update();
      this.dim();
      this.host.update();
    }
  }
  registerInstrument(tag, VatflowScreen);
}
vatflowRegisterScreen.hosts = {};
